import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/19-API_and_SDK_Standard.html","title":"API 与 SDK 规范","lang":"en-US","frontmatter":{},"filePathRelative":"19-API_and_SDK_Standard.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`19-API_and_SDK_Standard.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="api-与-sdk-规范" tabindex="-1"><a class="header-anchor" href="#api-与-sdk-规范"><span>API 与 SDK 规范</span></a></h1><blockquote><p>目的：统一对外运营/GM API、内部 gRPC 接口及客户端 SDK 协议，明确命名、认证、版本、幂等策略，替换 <code>docs/12</code> 中混合的 REST/gRPC 描述。</p></blockquote><h2 id="_1-总体结构" tabindex="-1"><a class="header-anchor" href="#_1-总体结构"><span>1. 总体结构</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌──────────────────────────────────────────┐</span>
<span class="line">│ 客户端 SDK (Unity/U3D)                   │</span>
<span class="line">│  • TCP/KCP 协议 (NetCore)                │</span>
<span class="line">│  • Protobuf 消息 (玩家实时)               │</span>
<span class="line">└────────────────┬────────────────────────┘</span>
<span class="line">                 │</span>
<span class="line">┌────────────────▼────────────────────────┐</span>
<span class="line">│ Gate/Zone/服务内部 gRPC/TCP 通信          │</span>
<span class="line">│  • Protobuf RPC                          │</span>
<span class="line">│  • Transport (NNG/TCP/IPC)               │</span>
<span class="line">└────────────────┬────────────────────────┘</span>
<span class="line">                 │</span>
<span class="line">┌────────────────▼────────────────────────┐</span>
<span class="line">│ 运维/运营 API (HTTP/gRPC)                │</span>
<span class="line">│  • GM 控制台 / BI / SDK 后台             │</span>
<span class="line">│  • 鉴权/审计/幂等                        │</span>
<span class="line">└──────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_2-内部-grpc-tcp-api" tabindex="-1"><a class="header-anchor" href="#_2-内部-grpc-tcp-api"><span>2. 内部 gRPC / TCP API</span></a></h2><h3 id="_2-1-命名与版本" tabindex="-1"><a class="header-anchor" href="#_2-1-命名与版本"><span>2.1 命名与版本</span></a></h3><ul><li><code>package apollo.gameservice.v1</code> 等形式，按服务划分（player, guild, chat...）。</li><li>Proto 文件位于 <code>Tool/pb/internal</code>，生成 C++/Go/Python stub。</li></ul><h3 id="_2-2-认证" tabindex="-1"><a class="header-anchor" href="#_2-2-认证"><span>2.2 认证</span></a></h3><ul><li>内网服务通过 mTLS 或 Token（由 ServiceRegistry 下发），所有 RPC 附带 <code>metadata</code>（server_id, trace_id）。</li><li>在 Transport 层内置 ACL，避免未授权服务访问。</li></ul><h3 id="_2-3-幂等和重试" tabindex="-1"><a class="header-anchor" href="#_2-3-幂等和重试"><span>2.3 幂等和重试</span></a></h3><ul><li>请求需包含 <code>request_id</code>；服务端可记录最近请求，防止重复执行。</li><li>返回统一 <code>Status</code>（code, message）；错误码在 <code>base/status.proto</code> 定义，分 CLIENT/RETRY/FAILURE。</li></ul><h3 id="_2-4-示例" tabindex="-1"><a class="header-anchor" href="#_2-4-示例"><span>2.4 示例</span></a></h3><div class="language-protobuf line-numbers-mode" data-highlighter="prismjs" data-ext="protobuf"><pre><code class="language-protobuf"><span class="line"><span class="token keyword">service</span> <span class="token class-name">ZoneControl</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">rpc</span> <span class="token function">TransferPlayer</span><span class="token punctuation">(</span><span class="token class-name">TransferPlayerRequest</span><span class="token punctuation">)</span> <span class="token keyword">returns</span> <span class="token punctuation">(</span><span class="token class-name">TransferPlayerResponse</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">rpc</span> <span class="token function">NotifySceneEvent</span><span class="token punctuation">(</span><span class="token class-name">SceneEventRequest</span><span class="token punctuation">)</span> <span class="token keyword">returns</span> <span class="token punctuation">(</span><span class="token class-name">google.protobuf.Empty</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-客户端-sdk-接口" tabindex="-1"><a class="header-anchor" href="#_3-客户端-sdk-接口"><span>3. 客户端 SDK 接口</span></a></h2><h3 id="_3-1-sdk-结构" tabindex="-1"><a class="header-anchor" href="#_3-1-sdk-结构"><span>3.1 SDK 结构</span></a></h3><ul><li><code>ApolloClient</code>：管理连接、加密、心跳、断线重连。</li><li><code>MessageRouter</code>：注册消息 ID -&gt; 回调（C# 事件）。</li><li><code>Serializer</code>：使用 Protobuf（<code>Tool/pb/fugumessage</code>）。</li><li>提供 Demo（Unity 包）+ 文档 + 自动化测试。</li></ul><h3 id="_3-2-关键能力" tabindex="-1"><a class="header-anchor" href="#_3-2-关键能力"><span>3.2 关键能力</span></a></h3><ul><li><strong>连接</strong>：支持 TCP/KCP（默认 TCP）；可选 WebSocket。</li><li><strong>安全</strong>：握手校验版本、设备、签名；握手后协商 AES/ChaCha。</li><li><strong>心跳/保活</strong>：SDK 自动发送心跳，超时触发重连。</li><li><strong>幂等</strong>：客户端发送消息时附带 <code>seq</code>，配合服务器 NetCore 去重。</li><li><strong>灰度</strong>：SDK 可获取 <code>slot</code> 信息（例如 A/B 测试），用于配置/资源选择。</li></ul><h3 id="_3-3-api-示例-c" tabindex="-1"><a class="header-anchor" href="#_3-3-api-示例-c"><span>3.3 API 示例（C#）</span></a></h3><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name"><span class="token keyword">var</span></span> client <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">ApolloClient</span><span class="token punctuation">(</span>config<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">client<span class="token punctuation">.</span>OnConnected <span class="token operator">+=</span> <span class="token range operator">..</span><span class="token punctuation">.</span><span class="token punctuation">;</span></span>
<span class="line">client<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span>PlayerMove<span class="token punctuation">.</span>MsgId<span class="token punctuation">,</span> msg <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> <span class="token range operator">..</span><span class="token punctuation">.</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">await</span> client<span class="token punctuation">.</span><span class="token function">ConnectAsync</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">client<span class="token punctuation">.</span><span class="token function">Send</span><span class="token punctuation">(</span>PlayerMove<span class="token punctuation">.</span>MsgId<span class="token punctuation">,</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">PlayerMove</span> <span class="token punctuation">{</span> <span class="token range operator">..</span><span class="token punctuation">.</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-运维-运营-api-http-grpc" tabindex="-1"><a class="header-anchor" href="#_4-运维-运营-api-http-grpc"><span>4. 运维/运营 API (HTTP/gRPC)</span></a></h2><h3 id="_4-1-设计原则" tabindex="-1"><a class="header-anchor" href="#_4-1-设计原则"><span>4.1 设计原则</span></a></h3><ul><li>RESTful 或 gRPC（选定一种作为主接口，可根据场景决定）。对外建议使用 HTTP/JSON + gRPC Gateway。</li><li>所有接口必须鉴权（OAuth2/JWT/API Key/签名），并有 RBAC 控制。</li><li>提供统一错误码、请求/响应格式、审计日志。</li><li>与业务实时链路解耦（单独 Gateway/服务）。</li></ul><h3 id="_4-2-基础结构" tabindex="-1"><a class="header-anchor" href="#_4-2-基础结构"><span>4.2 基础结构</span></a></h3><ul><li>API Gateway（内部部署）负责认证、限流、防刷、路由到具体服务。</li><li>每个服务提供 Swagger/Proto 描述，自动生成文档。</li></ul><h3 id="_4-3-请求-响应格式" tabindex="-1"><a class="header-anchor" href="#_4-3-请求-响应格式"><span>4.3 请求/响应格式</span></a></h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line">POST /api/v1/players/unlock</span>
<span class="line">Headers<span class="token operator">:</span></span>
<span class="line">  Authorization<span class="token operator">:</span> Bearer &lt;token&gt;</span>
<span class="line">  X-Request-Id<span class="token operator">:</span> &lt;uuid&gt;</span>
<span class="line">Body<span class="token operator">:</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;player_id&quot;</span><span class="token operator">:</span> <span class="token number">12345</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;server_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;1-2-6-1&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;reason&quot;</span><span class="token operator">:</span> <span class="token string">&quot;GM_UNLOCK&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line">Response<span class="token operator">:</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;OK&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;request_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>错误码按照 <code>StatusCode</code>（0 成功、1000-1999 客户端、2000+ 服务器）。</li><li>幂等：要求客户端提供 <code>X-Idempotency-Key</code>，服务端存储短期记录。</li></ul><h3 id="_4-4-常见-api-分组" tabindex="-1"><a class="header-anchor" href="#_4-4-常见-api-分组"><span>4.4 常见 API 分组</span></a></h3><ul><li><strong>账号/封禁</strong>：封号、解封、踢下线。</li><li><strong>角色管理</strong>：重置副本、修改属性、补发道具。</li><li><strong>活动配置</strong>：开启/关闭活动、灰度发布。</li><li><strong>监控/操作</strong>：查看服务器状态、触发脚本、重载配置。</li></ul><h2 id="_5-命名与版本策略" tabindex="-1"><a class="header-anchor" href="#_5-命名与版本策略"><span>5. 命名与版本策略</span></a></h2><ul><li>Proto/HTTP 版本采用语义化（<code>v1</code>, <code>v1alpha</code>...），重大变更新增版本，旧版维护一段时间。</li><li>SDK 使用 SemVer，接口变化写入 Release Note。</li><li>消息 ID（客户端）和 HTTP API 路径遵循统一命名规范，避免冲突。</li></ul><h2 id="_6-文档与工具" tabindex="-1"><a class="header-anchor" href="#_6-文档与工具"><span>6. 文档与工具</span></a></h2><ul><li>使用 <code>protoc</code> + <code>buf</code> 管理 IDL，生成 C++/C#/Go/Python/TS 等多语言代码。</li><li>REST API 使用 OpenAPI 3.0 描述，自动生成客户端/文档。</li><li>SDK 文档包括集成指南、协议说明、错误码、调试工具、示例场景。</li></ul><h2 id="_7-安全与审计" tabindex="-1"><a class="header-anchor" href="#_7-安全与审计"><span>7. 安全与审计</span></a></h2><ul><li>所有外部 API 请求/响应记录日志（带 request_id、user、时间、参数）。</li><li>关键操作（例如发放奖励）需二次确认或审批流程。</li><li>TLS/HTTPS 全局开启；内部 gRPC 使用 mTLS。</li></ul><h2 id="_8-roadmap" tabindex="-1"><a class="header-anchor" href="#_8-roadmap"><span>8. Roadmap</span></a></h2><ol><li>重写 <code>docs/12</code> API 文档，拆分内部 gRPC / 外部 HTTP ，并生成 Proto/OpenAPI。</li><li>完成 Unity SDK 初版（结合 <code>NetCore</code> 设计），包括示例项目。</li><li>建立认证/授权服务（OAuth2/Keycloak/自研），供 API Gateway 使用。</li><li>完成自动化文档（buf/OpenAPI）+ CI 检查。</li><li>逐步开放 GM/BI 接口，并集成审计/审批流程。</li></ol><hr><p>该规范将帮助服务器与客户端、运维 API 形成一致接口标准，支撑对外 SDK 与后台工具接入。***</p>`,40)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};